mapper.insert:
insert into workspaces(
    workspace_id, name, root_path, status, linux_server_id, trace_id, created_at, updated_at
) values (
    #{workspaceId}, #{name}, #{rootPath}, #{status}, #{linuxServerId}, #{traceId}, #{createdAt}, #{updatedAt}
)
on conflict (workspace_id) do nothing

insert into workspaces(
    workspace_id, name, root_path, status, linux_server_id, trace_id, created_at, updated_at
)
select #{workspaceId}, #{name}, #{rootPath}, #{status}, #{linuxServerId}, #{traceId}, #{createdAt}, #{updatedAt}
where not exists (
    select 1 from workspaces where workspace_id = #{workspaceId}
)

insert into experience_workspace_bindings(
    linux_server_id, workspace_id, configured_parameter_value, trace_id, created_at, updated_at
) values (
    #{linuxServerId}, #{workspaceId}, #{configuredParameterValue}, #{traceId}, #{createdAt}, #{updatedAt}
)
on conflict (linux_server_id) do nothing

insert into experience_workspace_bindings(
    linux_server_id, workspace_id, configured_parameter_value, trace_id, created_at, updated_at
) select
    #{linuxServerId}, #{workspaceId}, #{configuredParameterValue}, #{traceId}, #{createdAt}, #{updatedAt}
where not exists (
    select 1 from experience_workspace_bindings where linux_server_id = #{linuxServerId}
