mapper.update:
update experience_workspace_bindings
set workspace_id = #{binding.workspaceId},
    configured_parameter_value = #{binding.configuredParameterValue},
    trace_id = #{binding.traceId},
    updated_at = #{binding.updatedAt}
where linux_server_id = #{expected.linuxServerId}
  and workspace_id = #{expected.workspaceId}
